ace, route_status = excluded.route_status, route_target_kind = excluded.route_target_kind, target_origin_url = excluded.target_origin_url, connector_id = COALESCE(excluded.connector_id, workspace_route_registry.connector_id), connector_status = COALESCE(excluded.connector_status, workspace_route_registry.connector_status), record_json = json_set(excluded.record_json, '$.defaultNodeId', COALESCE(json_extract(excluded.record_json, '$.defaultNodeId'), json_extract(workspace_route_registry.record_json, '$.defaultNodeId')), '$.nodeTargets', json(COALESCE(json_extract(excluded.record_json, '$.nodeTargets'), json_extract(workspace_route_registry.record_json, '$.nodeTargets'), '[]')), '$.routes', json((SELECT json_group_array(json(value)) FROM ( SELECT old_route.value AS value FROM json_each(workspace_route_registry.record_json, '$.routes') AS old_route WHERE json_extract(old_route.value, '$.target.kind') IN ('os-connector', 'service-upstream') AND NOT EXISTS ( SELECT 1 FROM json_each(excluded.record_json, '$.routes') AS new_route WHERE json_extract(new_route.value, '$.surface') = json_extract(old_route.value, '$.surface') AND json_extract(new_route.value, '$.pathPrefix') = json_extract(old_route.value, '$.pathPrefix') ) UNION ALL SELECT new_route.value AS value FROM json_each(excluded.record_json, '$.routes') AS new_route )))), updated_at = datetime('now') WHERE COALESCE(json_extract(workspace_route_registry.record_json, '$.status'), 'active') <> 'revoked';
